import { useState, useEffect, useRef } from 'react';
import { searchCharacters } from './BangumiRequest';
import styles from './styles/InputStyles.module.css';

function SearchDropdown() {
  const [inputTerm, setInputTerm] = useState('');
  const [results, setResults] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef(null);

  // 点击外部关闭下拉框
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // 搜索函数
  const handleSearch = () => {
    if (!inputTerm.trim()) {
      setResults([]);
      return;
    }

    setIsLoading(true);
    setIsOpen(true);

    searchCharacters(inputTerm)
      .then(data => {
        setResults(data); // 更新结果数据
      })
      .catch(error => {
        console.error('搜索失败:', error);
        setResults([]); // 错误时清空结果
      })
      .finally(() => {
        setIsLoading(false);
      });
  };

  // 监听results变化
  useEffect(() => {
    console.log('结果已更新:', results);
    // 可以根据results内容做其他操作
  }, [results]);

  return (
    <div className = "App">
        <div className={styles.searchContainer} ref={dropdownRef}>
        <div className={styles.searchBox}>
            <input
            type="text"
            value={inputTerm}
            onChange={(e) => setInputTerm(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
            placeholder="输入角色名..."
            className={styles.searchInput}
            />
            <button
            onClick={handleSearch}
            disabled={isLoading}
            className={styles.searchButton}
            >
            {isLoading ? '搜索中...' : '搜索'}
            </button>
        </div>

        {/* 下拉框 - 内容会随results自动更新 */}
        {isOpen && (
            <div className={styles.dropdown}>
            {isLoading ? (
                <div className={styles.dropdownItem}>加载中...</div>
            ) : results.length > 0 ? (
                results.map(item => (
                <div
                    key={item.id}
                    className={styles.dropdownItem}
                    onClick={() => {
                    console.log('选中角色：',item.name);
                    setInputTerm(item.name);
                    setIsOpen(false);
                    }}
                >
                    搜索结果：{item.name}
                </div>
                ))
            ) : (
                <div className={styles.dropdownItem}>未找到结果</div>
            )}
            </div>
        )}
        </div>
    </div>
  );
}

export default SearchDropdown;
